from itertools import permutations, product

def parse_polyomino(lines):
    grid = [list(line.strip()) for line in lines]
    coords = [(r, c) for r in range(4) for c in range(4) if grid[r][c] == '#']
    min_r = min(r for r, c in coords)
    min_c = min(c for r, c in coords)
    normalized = sorted((r - min_r, c - min_c) for r, c in coords)
    return tuple(normalized)

def rotate(poly):
    return tuple(sorted((c, -r) for r, c in poly))

def normalize(poly):
    min_r = min(r for r, c in poly)
    min_c = min(c for r, c in poly)
    return tuple(sorted((r - min_r, c - min_c) for r, c in poly))

def translate_to(poly, dr, dc):
    return tuple((r + dr, c + dc) for r, c in poly)

def fits_in_grid(poly):
    return all(0 <= r < 4 and 0 <= c < 4 for r, c in poly)

def place_poly(grid, poly):
    for r, c in poly:
        if grid[r][c] != 0:
            return False
    for r, c in poly:
        grid[r][c] = 1
    return True

def remove_poly(grid, poly):
    for r, c in poly:
        grid[r][c] = 0

def solve():
    lines = []
    for _ in range(12):
        lines.append(input().strip())

    p1_lines = lines[0:4]
    p2_lines = lines[4:8]
    p3_lines = lines[8:12]

    poly1 = parse_polyomino(p1_lines)
    poly2 = parse_polyomino(p2_lines)
    poly3 = parse_polyomino(p3_lines)

    # Generate all orientations for each polyomino
    def get_orientations(poly):
        seen = set()
        result = []
        current = normalize(poly)
        for _ in range(4):
            norm = normalize(current)
            if norm not in seen:
                seen.add(norm)
                result.append(norm)
            current = rotate(current)
        return result

    or1 = get_orientations(poly1)
    or2 = get_orientations(poly2)
    or3 = get_orientations(poly3)

    # Try all combinations of placements
    for o1 in or1:
        for dr1, dc1 in product(range(4), repeat=2):
            placed1 = translate_to(o1, dr1, dc1)
            if not fits_in_grid(placed1):
                continue
            for o2 in or2:
                for dr2, dc2 in product(range(4), repeat=2):
                    placed2 = translate_to(o2, dr2, dc2)
                    if not fits_in_grid(placed2):
                        continue
                    # Check overlap
                    if set(placed1) & set(placed2):
                        continue
                    for o3 in or3:
                        for dr3, dc3 in product(range(4), repeat=2):
                            placed3 = translate_to(o3, dr3, dc3)
                            if not fits_in_grid(placed3):
                                continue
                            if set(placed1) & set(placed3) or set(placed2) & set(placed3):
                                continue
                            full = set(placed1) | set(placed2) | set(placed3)
                            if len(full) == 16:
                                print("Yes")
                                return
    print("No")

solve()
