import sys
from itertools import permutations

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data: 
        return
    n, m = map(int, data[0].split())
    edges = {}
    for i in range(1, m+1):
        u, v, w = map(int, data[i].split())
        edges[(u, v)] = min(edges.get((u, v), float('inf')), w)

    INF = float('inf')

    # Floyd-Warshall to get shortest paths between all pairs
    dist = [[INF] * (n+1) for _ in range(n+1)]
    for i in range(1, n+1):
        dist[i][i] = 0

    for (u, v), w in edges.items():
        dist[u][v] = min(dist[u][v], w)

    for k in range(1, n+1):
        for i in range(1, n+1):
            for j in range(1, n+1):
                if dist[i][k] != INF and dist[k][j] != INF:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Check if graph is strongly connected (all pairs reachable)
    for i in range(1, n+1):
        for j in range(1, n+1):
            if dist[i][j] == INF:
                print("No")
                return

    # dp[mask][i]: min cost to visit vertices in mask, ending at vertex i
    dp = {}
    for i in range(1, n+1):
        dp[(1 << (i-1), i)] = 0

    full_mask = (1 << n) - 1

    for mask in range(1, full_mask + 1):
        for last in range(1, n+1):
            if (mask & (1 << (last-1))) == 0:
                continue
            state = (mask, last)
            if state not in dp:
                continue
            cur_cost = dp[state]

            # Try to extend to any next vertex
            for nxt in range(1, n+1):
                if dist[last][nxt] == INF:
                    continue
                new_mask = mask | (1 << (nxt-1))
                new_state = (new_mask, nxt)
                new_cost = cur_cost + dist[last][nxt]
                if new_state not in dp or dp[new_state] > new_cost:
                    dp[new_state] = new_cost

    ans = INF
    for last in range(1, n+1):
        state = (full_mask, last)
        if state in dp:
            ans = min(ans, dp[state])

    if ans == INF:
        print("No")
    else:
        print(ans)

solve()
```

