def sortVowels(s):
    vowels = set('aeiouAEIOU')

    # Extract vowels and sort them by ASCII value
    vowel_chars = []
    for char in s:
        if char in vowels:
            vowel_chars.append(char)

    # Sort vowels by ASCII value
    vowel_chars.sort()

    # Reconstruct the string with sorted vowels
    result = []
    vowel_index = 0

    for char in s:
        if char in vowels:
            result.append(vowel_chars[vowel_index])
            vowel_index += 1
        else:
            result.append(char)

    return ''.join(result)
