def minExtraChar(s: str, dictionary) -> int:
    n = len(s)
    word_set = set(dictionary)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + 1
        for j in range(i):
