def minBalancedPartition(s):
    n = len(s)
    memo = {}

    def is_balanced(sub):
        if not sub:
            return False
        freq = {}
        for ch in sub:
            freq[ch] = freq.get(ch, 0) + 1
        values = list(freq.values())
        return all(v == values[0] for v in values)

    def dp(i):
        if i == n:
            return 0
        if i in memo:
            return memo[i]

        res = float('inf')
        for j in range(i + 1, n + 1):
            if is_balanced(s[i:j]):
                res = min(res, 1 + dp(j))
        memo[i] = res
        return res

    return dp(0)
```

