def maxLengthSubstring(s: str) -> int:
    max_len = 0
    left = 0
    char_count = {}

    for right in range(len(s)):
        char = s[right]
        char_count[char] = char_count.get(char, 0) + 1

        while char_count[char] > 2:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
