from collections import deque

def continuousSubarrays(nums):
    min_q = deque()
    max_q = deque()
    left = 0
    result = 0

    for right, num in enumerate(nums):
        while min_q and nums[min_q[-1]] >= num:
            min_q.pop()
        min_q.append(right)

        while max_q and nums[max_q[-1]] <= num:
            max_q.pop()
        max_q.append(right)

        while nums[max_q[0]] - nums[min_q[0]] > 2:
            left += 1
            if min_q[0] < left:
                min_q.popleft()
            if max_q[0] < left:
                max_q.popleft()

        result += right - left + 1

    return result
```

