def longest_common_suffix_index(wordsContainer, wordsQuery):
    def common_suffix_length(a, b):
        min_length = min(len(a), len(b))
        for i in range(1, min_length + 1):
            if a[-i] != b[-i]:
                return i - 1
        return min_length

    results = []
    for query in wordsQuery:
        max_suffix_length = -1
        best_index = -1

        for i, container_word in enumerate(wordsContainer):
            suffix_len = common_suffix_length(container_word, query)

            if suffix_len > max_suffix_length:
                max_suffix_length = suffix_len
                best_index = i
            elif suffix_len == max_suffix_length:
                if best_index == -1 or len(container_word) < len(wordsContainer[best_index]) or (
                        len(container_word) == len(wordsContainer[best_index]) and i < best_index):
                    best_index = i

        results.append(best_index)

    return results
