def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    bits = [0] * 32

    for num in nums:
        for i in range(32):
            if num & (1 << i):
                bits[i] += 1

    result = 0
    for _ in range(k):
        num = 0
        for i in range(31, -1, -1):
