def solve():
    import sys
    from itertools import combinations

    # Read input
    line = sys.stdin.readline().strip()
    N, T, M = map(int, line.split())

    # Read incompatible pairs
    incompatible = []
    for _ in range(M):
        a, b = map(int, sys.stdin.readline().split())
        incompatible.append((a-1, b-1))  # Convert to 0-indexed

    def is_valid_partition(partition):
        # Check if the partition has exactly T non-empty teams
        if len(partition) != T:
            return False

        # Check incompatible pairs
        for a, b in incompatible:
            # Find which team each player belongs to
            team_a = None
            team_b = None
            for i, team in enumerate(partition):
                if a in team:
                    team_a = i
                if b in team:
                    team_b = i
            # If both players exist and are in the same team, invalid
            if team_a is not None and team_b is not None and team_a == team_b:
                return False
        return True

    def generate_partitions(elements, k):
        # Generate all ways to partition 'elements' into k non-empty subsets
        if k == 1:
            yield [set(elements)]
            return

        if len(elements) == k:
            # Each element in its own set
            yield [[e] for e in elements]
            return

        if k > len(elements):
            return

        first = elements[0]
        rest = elements[1:]

        # Case 1: first element is alone in its subset
        for partition in generate_partitions(rest, k-1):
            yield [set([first])] + partition

        # Case 2: first element is added to one of the existing subsets
        for partition in generate_partitions(rest, k):
            for i in range(k):
                # Add first to the i-th subset
                new_partition = []
                for j, subset in enumerate(partition):
                    if j == i:
                        new_partition.append(subset | {first})
                    else:
                        new_partition.append(subset.copy())
                yield new_partition

    count = 0
    players = list(range(N))

    # Generate all possible partitions of N players into T teams
    for partition in generate_partitions(players, T):
        if is_valid_partition(partition):
            count += 1

    print(count)

