        if k <= 0:
            break

        current_char = s_list[i]
        # Try to change current_char to 'a' if possible
        dist_to_a = min(ord(current_char) - ord('a'), ord('z') - ord(current_char) + 1)

        if dist_to_a <= k:
            s_list[i] = 'a'
            k -= dist_to_a
        else:
            # Change to the lexicographically smallest char within remaining k
            new_char_code = ord(current_char) - k
            if new_char_code < ord('a'):
                new_char_code = ord('a') + (ord('a') - new_char_code - 1) % 26
            s_list[i] = chr(new_char_code)
            k = 0

    return ''.join(s_list)
