def min_operations(s1: str, s2: str, s3: str) -> int:
    # Find the longest common prefix
    i = 0
    while i < len(s1) and i < len(s2) and i < len(s3) and s1[i] == s2[i] == s3[i]:
        i += 1

    # If no common prefix exists, impossible to make them equal
    if i == 0:
        return -1

    # Calculate total operations needed to trim all strings to the common prefix
    return (len(s1) - i) + (len(s2) - i) + (len(s3) - i)
