def maximumSumOfPairs(nums1, nums2, queries):
    n = len(nums1)
    pairs = sorted([(nums1[i], nums2[i]) for i in range(n)], key=lambda x: -x[0])

    # Monotonic stack to keep track of points with increasing nums2 and max sum
    stack = []
    for a, b in pairs:
        s = a + b
        while stack and stack[-1][1] <= b and stack[-1][2] <= s:
            stack.pop()
        if not stack or stack[-1][1] < b:
            stack.append((a, b, s))

    res = []
    for x, y in queries:
        # Binary search for first element with a >= x
        lo, hi = 0, len(stack)
        while lo < hi:
            mid = (lo + hi) // 2
            if stack[mid][0] >= x:
                lo = mid + 1
            else:
                hi = mid
        idx = lo - 1

        ans = -1
        while idx >= 0:
            if stack[idx][1] >= y:
                ans = stack[idx][2]
                break
            idx -= 1
        res.append(ans)

    return res
