def maximumSubarraySum(nums, k):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    max_sum = float('-inf')
    seen = {}

    for j in range(n):
        val = nums[j]
        # Check for nums[i] = val + k
        if val + k in seen:
            i = seen[val + k]
            max_sum = max(max_sum, prefix[j + 1] - prefix[i])
        # Check for nums[i] = val - k
        if val - k in seen:
            i = seen[val - k]
            max_sum = max(max_sum, prefix[j + 1] - prefix[i])

        # Store earliest index for each value
        if val not in seen:
            seen[val] = j

    return max_sum if max_sum != float('-inf') else 0
