def minimumTimeToInitialState(word, k):
    n = len(word)
    for t in range(1, n // k + 2):
        suffix_start = t * k
        if suffix_start >= n:
            return t
        if word.startswith(word[suffix_start:]):
            return t
    return n // k + 1
