def minimumCoins(prices):
    n = len(prices)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            if j + j + 1 >= i:
                dp[i] = min(dp[i], dp[j] + prices[j])
    return dp[n]
