def medianOfUniquenessArray(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    median_pos = (total_subarrays + 1) // 2  # 1-indexed position of median

    def count_at_most(k):
        left = 0
        count = 0
        freq = {}
        distinct = 0
        for right in range(n):
            val = nums[right]
            freq[val] = freq.get(val, 0) + 1
            if freq[val] == 1:
                distinct += 1
            while distinct > k:
                left_val = nums[left]
                freq[left_val] -= 1
                if freq[left_val] == 0:
                    distinct -= 1
                left += 1
            count += (right - left + 1)
        return count

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= median_pos:
            hi = mid
        else:
            lo = mid + 1
    return lo
