def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    # count how many numbers have each bit set (bits 0..30)
    cnt = [0] * 31
    for num in nums:
        for b in range(31):
            if num >> b & 1:
                cnt[b] += 1

    # top will hold the values of the k numbers we are building
    top = [0] * k

    # process bits from most significant to least
    for b in range(30, -1, -1):
        take = min(cnt[b], k)
        if take == 0:
            continue
        val = 1 << b
        # assign this bit to the 'take' largest numbers (first 'take' in descending order)
        for i in range(take):
            top[i] += val

    # sum of squares of the k largest numbers modulo 1e9+7
    ans = 0
    for v in top:
        ans = (ans + v * v) % MOD
    return ans
