def sumOfPowers(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    nums.sort()
    total = 0

    for i in range(n):
        for j in range(i + 1, n):
            diff = nums[j] - nums[i]
            # Count subsequences of length k where nums[i] and nums[j] are the min and max
            # We need to pick k-2 elements from the elements between i and j (exclusive)
            between = j - i - 1
            if between >= k - 2:
                total = (total + diff * comb(between, k - 2)) % MOD

    return total

def comb(n, r):
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1
    r = min(r, n - r)
    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result
