    board = [[0] * W for _ in range(H)]

    # precompute orientation pairs for each tile
    orientations = []
    for a, b in tiles:
        if a == b:
            orientations.append([(a, b)])
        else:
            orientations.append([(a, b), (b, a)])

    def find_empty():
        for r in range(H):
            for c in range(W):
                if board[r][c] == 0:
                    return r, c
        return None

    def can_place(r, c, a, b):
        if r + a > H or c + b > W:
            return False
        for dr in range(a):
            for dc in range(b):
                if board[r + dr][c + dc] != 0:
                    return False
        return True

    def place(r, c, a, b):
        for dr in range(a):
            for dc in range(b):
                board[r + dr][c + dc] = 1

    def remove(r, c, a, b):
        for dr in range(a):
            for dc in range(b):
                board[r + dr][c + dc] = 0

    used = [False] * N

    def dfs():
        empty = find_empty()
        if empty is None:
            return True  # board fully covered
        r, c = empty
        for i in range(N):
